// Package auth verifies the X-Api-Key tokens generated by the CCP frontend.
//
// A token is the hex SHA-256 of "{unix timestamp of the current UTC hour}{agent id}{agent username}".
// Valid tokens are derived from the instance's registered Connect users.
package auth

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"sync"
	"time"

	"github.com/tyler71/owlchirp/app/internal/connect"
)

// rebuildInterval controls how often the token set is regenerated within an
// hour, so newly added Connect users are picked up.
const rebuildInterval = 10 * time.Minute

type UserSource interface {
	RegisteredUsers(ctx context.Context) ([]connect.RegisteredUser, error)
}

type Verifier struct {
	users UserSource
	now   func() time.Time

	mu      sync.Mutex
	hour    int64
	builtAt time.Time
	tokens  map[string]connect.RegisteredUser
}

func NewVerifier(users UserSource) *Verifier {
	return &Verifier{users: users, now: time.Now}
}

func Token(hour int64, agentID, username string) string {
	sum := sha256.Sum256([]byte(strconv.FormatInt(hour, 10) + agentID + username))
	return hex.EncodeToString(sum[:])
}

// Verify reports whether token is valid for the current hour and, if so, which
// user it belongs to. Tokens from the previous hour are also accepted to
// tolerate clock skew at the boundary.
func (v *Verifier) Verify(ctx context.Context, token string) (connect.RegisteredUser, bool, error) {
	if token == "" {
		return connect.RegisteredUser{}, false, nil
	}

	now := v.now().UTC()
	hour := now.Truncate(time.Hour).Unix()

	v.mu.Lock()
	defer v.mu.Unlock()

	if hour != v.hour || now.Sub(v.builtAt) > rebuildInterval {
		users, err := v.users.RegisteredUsers(ctx)
		if err != nil {
			return connect.RegisteredUser{}, false, err
		}

		tokens := make(map[string]connect.RegisteredUser, len(users)*2)
		for _, u := range users {
			tokens[Token(hour, u.ID, u.Username)] = u
			tokens[Token(hour-3600, u.ID, u.Username)] = u
		}

		v.tokens = tokens
		v.hour = hour
		v.builtAt = now
	}

	user, ok := v.tokens[token]
	return user, ok, nil
}
